    // เทียบเชิงความหมาย: classify กลับต้องได้ element+ข้อความเหมือนต้นฉบับทุกบรรทัด
    // (`parseScript` นำเข้าที่หัวไฟล์อยู่แล้ว — เดิม re-import ซ้ำในบล็อกนี้ ทำให้ชื่อถูกบัง
    //  ทั้งบล็อก แล้วโค้ดที่อยู่ "ก่อนหน้า" บรรทัดนั้นเรียกไม่ได้เลย (TDZ))
    const semA = parseScript(spTab.sp.getMarkdown());
    const semB = parseScript(spOrig);
    check('บทหนัง round-trip กติกา v1 (element+ข้อความตรงทุกบรรทัด)',
          semA.length === semB.length &&
          semA.every((x, i) => x.el === semB[i].el && x.text === semB[i].text),
          JSON.stringify([semA, semB]));
    // Enter จาก character → dialogue · Tab วน element
    const { TextSelection: TS2 } = await import('prosemirror-state');
    const vsp = spTab.sp.view;
    let chPos = null;
    vsp.state.doc.forEach((n, off) => { if (chPos === null && n.attrs.el === 'character') chPos = off; });
    vsp.dispatch(vsp.state.tr.setSelection(TS2.create(vsp.state.doc, chPos + 1 + n2len(vsp, chPos))));
    function n2len(v, off) { return v.state.doc.nodeAt(off).content.size; }
    spTab.sp.enter();
    check('Enter หลังตัวละคร → บทพูด', spTab.sp.curElement() === 'dialogue');
    // [alpha.78] Enter **กลางบล็อก** ต้องผ่าบล็อกจริง — เดิมแทรกบล็อกเปล่าต่อท้ายอย่างเดียว
    // ข้อความไม่ถูกแบ่ง = พิมพ์แทรกกลางฉากที่เขียนไว้แล้วไม่ได้เลย
    {
      const blocksOf = () => { const a = []; vsp.state.doc.forEach((nd) => a.push(nd)); return a; };
      // เตรียมบล็อก "บรรยาย" ที่มีเนื้อหาแน่ ๆ แล้ววางเคอร์เซอร์กลางข้อความ
      spTab.sp.setElement('action');
      vsp.dispatch(vsp.state.tr.insertText('หน้าหลัง'));
      const before = blocksOf();
      let pos = null;
      vsp.state.doc.forEach((nd, off) => { if (nd.textContent === 'หน้าหลัง') pos = off; });
      check('[a78] เตรียมบล็อกกลางทางได้', pos !== null);
      vsp.dispatch(vsp.state.tr.setSelection(TS2.create(vsp.state.doc, pos + 1 + 4)));  // กลางพอดี
      spTab.sp.enter();
      const after = blocksOf();
      check('[a78] Enter กลางบล็อก → จำนวนบล็อกเพิ่ม 1', after.length === before.length + 1,
            `${before.length} → ${after.length}`);
      const i = after.findIndex((nd) => nd.textContent === 'หน้า');
      check('[a78] ท่อนหน้าเหลือข้อความก่อนเคอร์เซอร์', i >= 0,
            JSON.stringify(after.map((nd) => nd.textContent)));
      if (i >= 0) {
        check('[a78] ท่อนหลังได้ข้อความหลังเคอร์เซอร์ (ไม่ใช่บล็อกว่าง)',
              after[i + 1] && after[i + 1].textContent === 'หลัง',
              JSON.stringify(after[i + 1] && after[i + 1].textContent));
        check('[a78] ท่อนหลังคงชนิดเดิม (ผ่ากลางบรรยายต้องได้บรรยาย)',
              after[i + 1] && after[i + 1].attrs.el === 'action', after[i + 1] && after[i + 1].attrs.el);
        check('[a78] เคอร์เซอร์ไปอยู่ต้นท่อนหลัง',
              vsp.state.selection.$from.parent.textContent === 'หลัง' &&
              vsp.state.selection.$from.parentOffset === 0,
              vsp.state.selection.$from.parent.textContent + '@' + vsp.state.selection.$from.parentOffset);
      }
      // เลือกข้อความไว้แล้วกด Enter = ตัวที่เลือกต้องถูกแทนที่ ไม่ใช่ค้างอยู่
      const p2 = after.findIndex((nd) => nd.textContent === 'หน้า');
      let off2 = 0; vsp.state.doc.forEach((nd, o) => { if (nd.textContent === 'หน้า') off2 = o; });
      vsp.dispatch(vsp.state.tr.setSelection(TS2.create(vsp.state.doc, off2 + 1, off2 + 1 + 4)));
      spTab.sp.enter();
      const after2 = blocksOf();
      check('[a78] เลือกทั้งบล็อกแล้ว Enter → ข้อความที่เลือกหายไป',
            !after2.some((nd) => nd.textContent === 'หน้า'),
            JSON.stringify(after2.map((nd) => nd.textContent)) + ' | ' + p2);
      // คืนเคอร์เซอร์ไว้ท้ายบล็อก sp ตัวสุดท้าย (ห้ามปล่อยให้ไปค้างบนโหนดรูป — เทสถัดไปพิมพ์ต่อ)
      let lastOff = null, acc = 0;
      vsp.state.doc.forEach((nd) => {
        if (nd.type.name === 'sp') lastOff = acc + nd.nodeSize - 1;
        acc += nd.nodeSize;
      });
      if (lastOff !== null) vsp.dispatch(vsp.state.tr.setSelection(TS2.create(vsp.state.doc, lastOff)));
    }
    spTab.sp.cycle(1);
    // alpha.57a: TAB_CYCLE แทรก transition-in ไว้ก่อน transition → ถัดจากบทพูดคือ "ทรานซิชันเข้า"
    check('สลับ element ได้ (Ctrl+↑/↓ · Tab ไม่สลับแล้ว)', spTab.sp.curElement() === 'transition-in',
          spTab.sp.curElement());
    setElementBadge(spTab.sp.curElement());
    check('ป้าย element เป็น dropdown คลิกเลือกได้',
          $('#elem-badge').classList.contains('elem-pick') && typeof $('#elem-badge').onclick === 'function');
    spTab.sp.setElement('scene');
    check('เลือก element ตรงจาก setElement ได้', spTab.sp.curElement() === 'scene');
    spTab.sp.setElement('dialogue');
    vsp.dispatch(vsp.state.tr.insertText('ทดสอบพูด'));
    await saveTab(spTab);
    check('บันทึกบทหนังลงไฟล์ตามกติกา v1',
          parseMdFile(await kapi.readFile(spTab.file)).body.includes('ทดสอบพูด'));
    // SmartType ในช่องตัวละคร: เดาเฉพาะชื่อตัวละคร
    spTab.sp.setElement('character');
    vsp.dispatch(vsp.state.tr.insertText('ยัยแ'));
    spSmartCheck(spTab);
    check('SmartType บทหนังตาม element (ตัวละคร)', smart.visible &&
          smart.items.some((x) => x.includes('ยัยแมว')), JSON.stringify(smart.items));
    // Final Draft: จำชื่อตัวละครที่ "พิมพ์ในบท" แม้ไม่มีใน Wiki
    const terms = screenplayTerms(spTab);
    check('บทหนังเก็บชื่อตัวละครที่พิมพ์ในบท (Final Draft)',
          Array.isArray(terms.chars), JSON.stringify(terms.chars).slice(0, 60));
    smart.hide();
    // จัดหน้าในบทหนัง: setAlign เขียน attr align + curAlign อ่านกลับได้
    spTab.sp.setElement('action');
    spTab.sp.setAlign('center');
    check('บทหนัง: จัดหน้ากึ่งกลางได้ (setAlign/curAlign)', spTab.sp.curAlign() === 'center');
    check('บทหนัง: บล็อกมี style text-align จริงใน DOM',
          !!document.querySelector('.pane.on .sp[style*="center"]'));
    spTab.sp.setAlign('left');
    check('บทหนัง: คืนชิดซ้าย = ล้าง align (attr null)', spTab.sp.curAlign() === 'left');
    // บล็อกตัวละคร: ชื่อ Wiki กลายเป็นลิงก์ได้ (แต่ต้องเป็นลิงก์เดียวคลุมทั้งชื่อ ไม่ลามซ้ำ)
    spTab.sp.setElement('character');
    { const b = spTab.sp.curBlock();
      spTab.sp.view.dispatch(spTab.sp.view.state.tr.delete(b.pos + 1, b.pos + 1 + b.node.content.size)); }
    spTab.sp.view.dispatch(spTab.sp.view.state.tr.insertText('ยัยแมวเก้าชีวิต'));
    spTab.sp.refreshMentions(); refreshSpell(spTab.sp.view);
    await new Promise((r) => setTimeout(r, 40));
    const charMentions = document.querySelectorAll('.pane.on .sp-character .k-mention');
    check('บล็อกตัวละคร: ชื่อ Wiki เป็นลิงก์ได้ (Wiki link ในบทหนังใช้ได้ทุกบล็อก)',
          charMentions.length === 1, 'mentions=' + charMentions.length);
    check('บล็อกตัวละคร: ไม่มีขีดแดงตรวจคำผิด',
          !document.querySelector('.pane.on .sp-character .k-spell-bad'));
    await kapi.testShot('/tmp/k2_sp_fixed.png');
    // ถ่ายบทหนังในมุมมองปกติด้วย
    // [alpha.100 ข้อ 1] เดิมเทสนี้ยืนยันว่าบทหนังในมุมมองปกติเป็นแผ่นครีม — สัญญาเปลี่ยนแล้ว
    // (มุมมองปกติ = สายเนื้อหาบนพื้นโปรแกรม · แผ่นกระดาษอยู่ที่มุมมองจัดหน้าอย่างเดียว)
    check('[100-1] ★ บทหนังมุมมองปกติ: ไม่มีแผ่นกระดาษเช่นกัน (พื้นโปร่งใส)',
          /rgba\(0, 0, 0, 0\)|transparent/.test(
            getComputedStyle(document.querySelector('.pane.on .ProseMirror')).backgroundColor),
          getComputedStyle(document.querySelector('.pane.on .ProseMirror')).backgroundColor);
    await kapi.testShot('/tmp/k2_paper_sp.png');
    // กล่องขยายรูปทำงาน (lightbox)
    imageLightboxTest();
    function imageLightboxTest() {
      imageLightbox('file:///tmp/nope.png', 'ทดสอบ');
    }
    await new Promise((r) => setTimeout(r, 20));
    check('กล่องขยายรูป (lightbox) เปิดได้', !!document.querySelector('.k-lightbox .k-lightbox-img'));
    document.querySelector('.k-lightbox').click();          // คลิกปิด
    await new Promise((r) => setTimeout(r, 20));
    check('คลิกแล้วกล่องขยายรูปปิด', !document.querySelector('.k-lightbox'));

    // ================= v2.0.0-alpha.24: บทหนัง (รูป/Wiki/Final Draft) =================
    activate(spTab.file);
    await new Promise((r) => setTimeout(r, 100));
    const vsp2 = spTab.sp.view;
    // (8) SmartType แบบ Final Draft: หัวฉาก พิมพ์ "e" → EXT. (1 ตัว + ไม่สนพิมพ์เล็กใหญ่)
    spTab.sp.setElement('scene');
    { const b = spTab.sp.curBlock();
      vsp2.dispatch(vsp2.state.tr.delete(b.pos + 1, b.pos + 1 + b.node.content.size)); }
    vsp2.dispatch(vsp2.state.tr.insertText('e'));
    spSmartCheck(spTab);
    check('บทหนัง SmartType Final Draft: พิมพ์ e → EXT.',
          smart.visible && smart.items.some((x) => x.toUpperCase().startsWith('EXT')),
          JSON.stringify(smart.items));
    smart.hide();
    { const b = spTab.sp.curBlock();
      vsp2.dispatch(vsp2.state.tr.delete(b.pos + 1, b.pos + 1 + b.node.content.size)); }
    // (8) ลิงก์ Wiki ในบทหนัง: ใส่ชื่อในบรรยาย → มี .k-mention
    spTab.sp.setElement('action');
    { const b = spTab.sp.curBlock();
      vsp2.dispatch(vsp2.state.tr.insertText('เขาเจอ ยัยแมวเก้าชีวิต ที่นั่น', b.pos + 1)); }
    spTab.sp.refreshMentions();
    await new Promise((r) => setTimeout(r, 120));
    check('บทหนังไฮไลต์ชื่อ Wiki ได้ (.k-mention) — ลิงก์ไป Wiki',
          document.querySelectorAll('.pane.on .k-mention').length >= 1);
    // (7) รูปในบทหนังเป็น node จริง (spimage) ไม่กลายเป็น markdown
    const TSsp = (await import('prosemirror-state')).TextSelection;
    { const b = spTab.sp.curBlock();
      vsp2.dispatch(vsp2.state.tr.setSelection(TSsp.create(vsp2.state.doc, b.pos + 1 + b.node.content.size))); }
    spTab.sp.insertImage('../../Images/x.png', 'ภาพทดสอบบท', '![ภาพทดสอบบท](../../Images/x.png)');
    let hasSpImg = false;
    vsp2.state.doc.forEach((n) => { if (n.type.name === 'spimage') hasSpImg = true; });
    check('แทรกรูปในบทหนัง = node รูปจริง (spimage) ไม่ใช่ข้อความ', hasSpImg);
    check('รูปในบทหนัง render เป็น <figure><img> จริง',
          !!document.querySelector('.pane.on figure.sp-image img'));
    check('บทหนัง getMarkdown คงบรรทัดรูปเป็น ![..](..) — ไม่หลุดเป็นข้อความล้วน',
          spTab.sp.getMarkdown().includes('![ภาพทดสอบบท](../../Images/x.png)'));
    activate(t.file);

    // ---- Dashboard ----
    await openDashboard();
    await new Promise((r) => setTimeout(r, 600));
    check('แดชบอร์ดเปิด + ตัวเลขสถิติมา',
          isPanelOpen('dashboard') &&
          document.querySelector('#dash-body .dash-num')?.textContent !== '…');
    check('แดชบอร์ดมีแผงสถิติเชิงลึก (analytics)',
          !!document.querySelector('#dash-body .dash-analytics'));
    check('มีแถบความคืบหน้าตามสถานะฉาก',
          !!document.querySelector('#dash-body .dash-apanel .dash-stat-fill'));
    check('มีแผงความยาวแต่ละบท',
          [...document.querySelectorAll('#dash-body .dash-apanel-title')]
            .some((e) => e.textContent.includes('ความยาวแต่ละบท')));
    await kapi.testShot('/tmp/k2_analytics.png');

    // ══ [alpha.100] ★★ error เงียบ: แดชบอร์ดระเบิดทุกครั้งที่สลับโปรเจกต์ ══
    //
    // อาการ: ไม่มีอะไรผิดใน UI · e2e เขียวตลอด · แต่ log ของแอปมีทุกครั้งที่เปิดโปรเจกต์
    //   `ERROR วาดแผง dashboard ล้มเหลว | path:join ... Received null`
    // ต้นตอ: แดชบอร์ดอ่านไฟล์ทั้งโปรเจกต์ (await หลายสิบจุด) แล้วอ่าน `state.root` ใหม่ทุกครั้ง
    // ระหว่างทาง · พอโปรเจกต์ถูกปิดกลางคัน (`state.root = null`) รอบวนถัดไปก็ตาย
    // ของจริงตายที่ `join(null, 'Recycle')` = ลูปไล่โฟลเดอร์ระดับรากวนมาถึงใบที่ 9 พอดี
    //
    // ทำซ้ำตรง ๆ: สั่งวาดแล้ว **ไม่ await** · ดึงโปรเจกต์ออกจากใต้เท้าทันที · แล้วค่อยรอผล
    {
      const keepRoot100 = state.root;
      const errBefore = state._panelDrawErrors || 0;
      const job = renderDashboard($('#dash-body'));      // ยังไม่ await — ให้มันค้างกลางทาง
      state.root = null;                                 // เหมือน closeProjectIfAny() ทำ
      let threw = null, ret;
      try { ret = await job; } catch (e) { threw = e; }
      state.root = keepRoot100;
      check('[100-5] ★★ สลับโปรเจกต์ระหว่างวาดแดชบอร์ด → ไม่ throw',
            !threw, threw && threw.message);
      check('[100-5] ★★ และเลิกวาดอย่างสงบ (คืน false) ไม่ใช่วาดข้อมูลโปรเจกต์เก่าต่อ',
            ret === false, String(ret));
      check('[100-5] ★★ ไม่มี error เงียบเพิ่มในตัวนับของตัววาดแผง',
            (state._panelDrawErrors || 0) === errBefore,
            errBefore + ' → ' + (state._panelDrawErrors || 0) + ' · ' + (state._panelDrawLastErr || ''));
      // ยังไม่มีโปรเจกต์เลยก็ต้องไม่พัง (หน้าต่างแผงที่ฉีกออกมา/ตอนบูตเจอเคสนี้)
      state.root = null;
      let ret2, threw2 = null;
      try { ret2 = await renderDashboard($('#dash-body')); } catch (e) { threw2 = e; }
      state.root = keepRoot100;
      check('[100-5] ★ ยังไม่มีโปรเจกต์ → คืน false เงียบ ๆ ไม่ throw',
            !threw2 && ret2 === false, threw2 ? threw2.message : String(ret2));
      await openDashboard();                             // วาดกลับให้ครบตามเดิม
      await new Promise((r) => setTimeout(r, 500));
      check('[100-5] ★ วาดใหม่หลังคืนโปรเจกต์แล้วตัวเลขกลับมาครบ',
            document.querySelector('#dash-body .dash-num')?.textContent !== '…',
            document.querySelector('#dash-body .dash-num')?.textContent);
    }
    closeTab('::dash::');

    // ---- เวิร์กโฟลว์ส่งออก (compile) ----
    {
      const drafts = await listDrafts();
      check('listDrafts เจอฉบับร่างอย่างน้อย 1', drafts.length >= 1);
      const model = await buildDraftModel(drafts[0].dPath, 'เล่มทดสอบ compile');
      check('buildDraftModel: มีบท + ฉาก + นับคำ',
            model.chapters.length >= 1 && model.chapters[0].scenes.length >= 1 &&
            model.chapters[0].scenes.some((s) => s.words > 0));
      // พรีเซ็ต reader มีหน้าปก + ตัดโน้ต
      const rd = runWorkflow(model, PRESETS.find((p) => p.id === 'reader'));
      check('พรีเซ็ต reader: หน้าปกมีชื่อเรื่อง', rd.text.includes('# เล่มทดสอบ compile'));
      // html preset → ext html + แท็ก html
      const ht = runWorkflow(model, PRESETS.find((p) => p.id === 'html'));
      check('พรีเซ็ต html: ext=html + มี <h1', ht.ext === 'html' && /<h1[ >]/.test(ht.text));
      // plain preset → txt + ไม่มี ** จาก markdown
      const pl = runWorkflow(model, PRESETS.find((p) => p.id === 'plain'));
      check('พรีเซ็ต plain: ext=txt + ไม่มี ** ของ markdown', pl.ext === 'txt' && !pl.text.includes('**'));
      // ทำสำเนา → บันทึกลง meta
      const before = userWorkflows().length;
      const cloned = cloneWorkflow(PRESETS.find((p) => p.id === 'editor'));
      userWorkflows().push(cloned); await saveProjectMeta();
      const pjw = await kapi.readJson(await kapi.join(state.root, 'project.khn.json'));
      check('ทำสำเนาเวิร์กโฟลว์ → เก็บลง project.khn.json',
            Array.isArray(pjw.compileWorkflows) && pjw.compileWorkflows.length === before + 1);
      check('เวิร์กโฟลว์สำเนาแก้ได้ (builtIn=false)', cloned.builtIn === false);
      // เปิดกล่อง compile จริง + ดูตัวอย่าง
      const dlg = await openCompileDialog();
      await new Promise((r) => setTimeout(r, 60));
      check('กล่องส่งออกเวิร์กโฟลว์เปิด + มีรายการพรีเซ็ต',
            !!document.querySelector('.k-compile') &&
            document.querySelectorAll('.k-compile .cmp-wf').length >= PRESETS.length);
      dlg.select('html');
      document.querySelector('.k-compile .cmp-preview')
        && [...document.querySelectorAll('.k-compile .k-dlg-btns button')]
             .find((b) => b.textContent.includes('ดูตัวอย่าง'))?.click();
      await new Promise((r) => setTimeout(r, 120));
      check('กดดูตัวอย่างแล้วมีข้อความพรีวิว',
            (document.querySelector('.k-compile .cmp-preview')?.textContent || '').length > 5);
      await kapi.testShot('/tmp/k2_compile.png');
      document.querySelector('.k-compile .k-cancel').click();
    }

    // ---- หมวด Wiki ที่ผู้ใช้สร้างเอง ----
    {
      const nBefore = wikiCats().length;
      wikiCats().push({ key: 'factions', label: 'องค์กร/กลุ่ม', icon: '⚔' });
      await saveProjectMeta(); applyWikiCats();
      const wr = await wikiRoot();
      await kapi.mkdir(await kapi.join(wr, 'factions'));
      const pjc = await kapi.readJson(await kapi.join(state.root, 'project.khn.json'));
      check('สร้างหมวดเอง → เก็บลง project.khn.json',
            (pjc.wikiCats || []).some((c) => c.key === 'factions' && c.label === 'องค์กร/กลุ่ม'));
      check('catLabel/catIcon อ่านหมวดเองได้',
            catLabel('factions') === 'องค์กร/กลุ่ม' && catIcon('factions') === 'bookmark');
      check('applyWikiCats ใส่ชื่อไทยเข้า CAT_TH (เทมเพลตแสดงตรง)', CAT_TH.factions === 'องค์กร/กลุ่ม');
      // สร้าง entity ในหมวดเอง
      const fDir = await kapi.join(wr, 'factions');
      const pF = addEntity(fDir, 'factions');
      await new Promise((r) => setTimeout(r, 60));
      document.querySelector('#ent-name').value = 'สมาคมพ่อค้า';
      document.querySelector('.k-dialog .k-ok').click();
      await pF;
      await new Promise((r) => setTimeout(r, 200));
      const ents = await loadAllEntities();
      check('เพิ่ม entity ในหมวดเองได้ + entityTypeKey ตรงหมวด',
            ents.some((e) => e.name === 'สมาคมพ่อค้า' && e.cat === 'factions'));
      closeTab(state.active.file);
      // buildTree แสดงหมวดเอง (ไอคอน + ชื่อ)
      await buildTree();
      check('Explorer แสดงหมวดที่สร้างเอง',
            [...document.querySelectorAll('#tree .ch-title')].some((e) => e.textContent.includes('องค์กร/กลุ่ม')));
      // ลบหมวดที่ยังมีของ → ต้องกันไว้
      await deleteWikiCat('factions', fDir);
      check('ลบหมวดที่ยังมีรายการไม่ได้ (กันข้อมูลหาย)',
            wikiCats().some((c) => c.key === 'factions'));
      // หมวดหลักลบไม่ได้
      const before2 = wikiCats().length;
      await deleteWikiCat('characters', await kapi.join(wr, 'characters'));
      check('หมวดหลักลบไม่ได้', wikiCats().length === before2);
    }


    // ---- Relationships + inverse sync สองทาง ----
    const catDir2 = await kapi.join(state.root, 'Wiki', 'characters');
    const pE2 = addEntity(catDir2, 'characters');
    await new Promise((r) => setTimeout(r, 60));
    document.querySelector('#ent-name').value = 'น้องสาวทดสอบ';
    document.querySelector('.k-dialog .k-ok').click();
    await pE2;
    await new Promise((r) => setTimeout(r, 250));
    const relTab = state.active;
    relTab.wiki.e.relationships = [{ targetName: 'ยัยแมวเก้าชีวิต', role: 'พี่สาว', type: 'family' }];
    await relTab.wiki.save();
    relTab.wiki.render();
    await new Promise((r) => setTimeout(r, 120));
    {
      const dot = relTab.pane.querySelector('.rel-type-dot');
      check('หน้า Wiki มีจุดสีบอกประเภทความสัมพันธ์',
            !!dot && (dot.title || '').includes('ครอบครัว'), dot && dot.title);
      check('จุดสีใช้สีประจำประเภท (family = #e06c75)',
            !!dot && dot.style.background.replace(/\s/g, '') === 'rgb(224,108,117)',
            dot && dot.style.background);
    }
    await smart.loadNames(state.root);
    const catFile = smart.fileOf['ยัยแมวเก้าชีวิต'];
    check('fileOf พร้อมหลัง loadNames', !!catFile, JSON.stringify(Object.keys(smart.fileOf)));
    const catEnt = await kapi.readJson(catFile);
    check('ความสัมพันธ์ sync สองทาง + สลับบทบาท (พี่สาว↔น้อง)',
          (catEnt.relationships || []).some((r) =>
            r.targetName === 'น้องสาวทดสอบ' && r.role && r.role !== 'พี่สาว'),
          JSON.stringify(catEnt.relationships));
    check('ประเภทความสัมพันธ์ซิงก์ไปฝั่งตรงข้ามด้วย',
          (catEnt.relationships || []).some((r) =>
            r.targetName === 'น้องสาวทดสอบ' && r.type === 'family'),
          JSON.stringify(catEnt.relationships));
    check('ประเภทถูกเก็บลงไฟล์ของฝั่งที่ตั้ง',
          ((await kapi.readJson(relTab.file)).relationships || [])[0].type === 'family');
    closeTab(relTab.file);

    // ---- Story Network ----
    await openNetwork();
    await new Promise((r) => setTimeout(r, 500));
    // [alpha.62 บั๊ก 16] Story Network เป็นแผงแล้ว — อ่านจาก netInst ไม่ใช่แท็บ
    const netN = netInst;
    check('Story Network มีโหนด + เส้นความสัมพันธ์',
          netN.nodes.length >= 2 && netN.edges.length >= 1,
          `nodes=${netN.nodes.length} edges=${netN.edges.length}`);
    check('เส้นในกราฟมีประเภทติดมาด้วย (family จากที่ตั้งไว้)',
          netN.edges.some((e) => e.type === 'family'),
          JSON.stringify(netN.edges.map((e) => [e.role, e.type])));
    // [alpha.73 ข้อ 3] สีเส้นไม่ได้อยู่ใน REL_COLOR อีกแล้ว — ตารางสีจริงมาจาก network-theme.js
    // (เดิม network.js ยัด 'scene-link'/'co-occur'/'ent-scene' เข้า REL_COLOR ตอนโหลดโมดูล)
    check('ทุกเส้นได้ประเภทที่มีสีจริง (ไม่ระบุ = เดาจากบทบาท)',
          netN.edges.every((e) => !!netN._edgeCol[e.type]),
          JSON.stringify(netN.edges.map((e) => [e.type, netN._edgeCol[e.type]])));
    check('[73-3] ทุกประเภทเส้นที่ผังใช้ มีช่องให้ตั้งสีในตั้งค่า',
          [...new Set(netN.edges.map((e) => e.type))]
            .every((k) => NET_COLOR_DEFS.some((d) => d.target === 'edge' && d.id === k)),
          JSON.stringify([...new Set(netN.edges.map((e) => e.type))]));
    hidePanel('network');

    // ---- บรรยากาศรับรู้ของสถานที่ (Sensory Profiles) ----
    {
      const locDir = await kapi.join(await wikiRoot(), 'locations');
      await kapi.mkdir(locDir);
      const pLoc = addEntity(locDir, 'locations');
      await new Promise((r) => setTimeout(r, 80));
      document.querySelector('#ent-name').value = 'หอสมุดร้าง';
      { const ovs = [...document.querySelectorAll('.k-overlay')];
        ovs[ovs.length - 1].querySelector('.k-ok').click(); }
      await pLoc;
      await new Promise((r) => setTimeout(r, 300));
      const locTab = state.active;
      check('สถานที่ที่สร้างใหม่มี sensoryProfile ในไฟล์',
            typeof (await kapi.readJson(locTab.file)).sensoryProfile === 'object');
      const senSec = locTab.pane.querySelector('.wiki-sensory');
      check('หน้า Wiki สถานที่มีหัวข้อ “บรรยากาศรับรู้”', !!senSec);
      check('มีช่องครบ 5 ประสาทสัมผัส',
            senSec && senSec.querySelectorAll('.wiki-sensory-row').length === 5,
            senSec && senSec.querySelectorAll('.wiki-sensory-row').length);
      check('ช่องเรียงตาม เห็น/ได้ยิน/กลิ่น/สัมผัส/รสชาติ',
            [...senSec.querySelectorAll('.wiki-sensory-row')].map((r) => r.dataset.sense).join() ===
            'sight,sound,smell,touch,taste');
      // กรอกแล้วต้องเข้า entity + บันทึกลงไฟล์ได้
      const inSight = senSec.querySelector('[data-sense="sight"] input');
      inSight.value = 'ชั้นหนังสือสูงจรดเพดาน ฝุ่นลอยในลำแสง';
      inSight.dispatchEvent(new Event('input', { bubbles: true }));
      const inSmell = senSec.querySelector('[data-sense="smell"] input');
      inSmell.value = 'กลิ่นกระดาษเก่า';
      inSmell.dispatchEvent(new Event('input', { bubbles: true }));
      check('พิมพ์แล้วค่าเข้า entity.sensoryProfile',
            locTab.wiki.e.sensoryProfile.sight.startsWith('ชั้นหนังสือ'),
            JSON.stringify(locTab.wiki.e.sensoryProfile));
      check('กรอกแล้วหน้าถูกทำเครื่องหมายว่ายังไม่บันทึก', locTab.wiki.dirty === true);
      await locTab.wiki.save();
      const locJson = await kapi.readJson(locTab.file);
      check('บรรยากาศรับรู้เขียนกลับไฟล์ได้',
            locJson.sensoryProfile.sight.startsWith('ชั้นหนังสือ') &&
            locJson.sensoryProfile.smell === 'กลิ่นกระดาษเก่า',
            JSON.stringify(locJson.sensoryProfile));
      // วาดใหม่ต้องไม่ได้ช่องซ้ำ + ค่าที่กรอกยังอยู่
      locTab.wiki.render();
      await new Promise((r) => setTimeout(r, 120));
      const senSec2 = locTab.pane.querySelector('.wiki-sensory');
      check('render ซ้ำแล้วไม่มีช่องซ้ำ + ค่าที่กรอกยังอยู่',
            senSec2 && senSec2.querySelectorAll('.wiki-sensory-row').length === 5 &&
            senSec2.querySelector('[data-sense="smell"] input').value === 'กลิ่นกระดาษเก่า',
            senSec2 && senSec2.querySelectorAll('.wiki-sensory-row').length);
      closeTab(locTab.file);
      // ตัวละครต้องไม่มีหัวข้อนี้ (เฉพาะสถานที่)
      const charFile = smart.fileOf['ยัยแมวเก้าชีวิต'];
      await openEntity(charFile);
      await new Promise((r) => setTimeout(r, 250));
      check('หน้า Wiki ตัวละครไม่มีหัวข้อบรรยากาศรับรู้',
            !state.tabs.get(charFile).pane.querySelector('.wiki-sensory'));
      closeTab(charFile);
    }

    // ---- Planner v4 (กระดานวางแผนแบบ Miro) ----
    await openPlanner();
    await new Promise((r) => setTimeout(r, 350));
    const pb = plannerInst;
    check('Planner เปิดเป็นแผง + มี renderer canvas',
          !!(pb && pb.renderer && pb.renderer.canvas) && isPanelOpen('planner'), 'planner=' + !!pb);
    await pb._ready;

    // [บั๊ก 1+7] เลย์เอาต์: แถบเครื่องมือ/กรอง/เวที/สถานะ ต้องเรียงเป็นแถวไม่ทับกัน
    const plBody = $('#planner-body');
    const rToolbar = pb.toolbar.getBoundingClientRect();
    const rFilter = pb.filterBar.getBoundingClientRect();
    const rStage = pb.stage.getBoundingClientRect();
    const rStatus = pb.statusBar.getBoundingClientRect();
    check('Planner บั๊ก1: เวทีกระดานไม่ทับแถบเครื่องมือ/แถบกรอง (กดปุ่มได้)',
          rStage.top >= rFilter.bottom - 1 && rFilter.top >= rToolbar.bottom - 1 && rStage.height > 40,
          `tb=${Math.round(rToolbar.bottom)} f=${Math.round(rFilter.top)}/${Math.round(rFilter.bottom)} stage=${Math.round(rStage.top)}`);
    // เดิม canvas (absolute top:84px) ทับปุ่มแถวที่ 2 ของ toolbar ที่ wrap ลงมา → กดไม่โดน
    const saveHit = (() => {
      const strip = pb.toolbar.querySelector('.planner-toolbar-strip');
      const b = pb.toolbar.querySelector('[data-action="save"]');
      if (!strip || !b) return { ok: false, why: 'no button' };
      strip.style.scrollBehavior = 'auto';
      strip.scrollLeft = Math.max(0, b.offsetLeft - 30);       // เลื่อนแถบให้ปุ่มโผล่ก่อน (บั๊ก 7)
      const r = b.getBoundingClientRect();
      const hit = document.elementFromPoint(r.left + r.width / 2, r.top + r.height / 2);
      return { ok: !!hit && (hit === b || b.contains(hit)), why: hit ? hit.className || hit.tagName : 'none' };
    })();
    check('Planner บั๊ก1+7: เลื่อนแถบแล้วกดปุ่มบันทึกโดนจริง (elementFromPoint ชนปุ่ม ไม่ใช่ canvas)',
          saveHit.ok, saveHit.why);
    check('Planner บั๊ก7: แถบเครื่องมือเลื่อนแนวนอนได้ (nowrap + overflow-x)',
          getComputedStyle(pb.toolbar.querySelector('.planner-toolbar-strip')).overflowX === 'auto' &&
          !!pb.toolbar.querySelector('.planner-scroll-btn'));
    check('Planner บั๊ก8: แถบสถานะบอกพิกัด x/y ได้',
          !!rStatus.height && (pb.statusBar.setXY({ x: 12, y: 34 }),
          pb.statusBar.querySelector('#pl-st-xy').textContent.includes('12')),
          pb.statusBar.querySelector('#pl-st-xy').textContent);
    check('Planner บั๊ก4: รางเครื่องมือมีครบ (มือ/ข้อความ/รูปทรง/เฟรม/คอมเมนต์/โพสต์อิต/เส้นเชื่อม)',
          ['select', 'hand', 'sticky', 'text', 'shape', 'frame', 'comment', 'connector']
            .every((t) => !!pb.rail.querySelector(`[data-tool="${t}"]`)));

    const nA = pb._addNode('scene', 'ฉาก A', '#3f3e3a');
    const nB = pb._addNode('entity', 'ตัวละคร B', '#7a6f9f');
    nA.x = 120; nA.y = 120; nB.x = 420; nB.y = 280;
    nA.synopsis = 'พระเอกเปิดประตูเจอจดหมาย';
    nA.status = 'กำลังเขียน';
    nA.tags = ['เปิดเรื่อง'];
    nA.file = '/x/Chapters/c1/s1.md';
    pb.renderer.rebuildNode(nA); pb.renderer.rebuildNode(nB);
    const edge = pb._handleConnect(nA.id, 'right', nB.id, 'left');
    check('Planner v4 เพิ่มการ์ด 2 + เชื่อมเส้น 1 (port-based)',
          pb.data.getAllNodes().length === 2 && pb.data.getAllEdges().length === 1 && !!edge,
          'nodes=' + pb.data.getAllNodes().length + ' edges=' + pb.data.getAllEdges().length);
    check('Planner v4 กันเส้นเชื่อมซ้ำ', pb._handleConnect(nA.id, 'right', nB.id, 'left') === null);
    check('Planner v4 กัน self-loop', pb._handleConnect(nA.id, 'right', nA.id, 'left') === null);
    check('Planner v4 การ์ดวาดจริงบน canvas (มี object ชนิด node)',
          pb.renderer.canvas.getObjects().filter((o) => o.kind === 'node').length === 2);

    // [บั๊ก 9] เส้นเชื่อมมีรูปแบบเส้นทาง + [บั๊ก 11] หัวลูกศรเลือกได้
    check('Planner บั๊ก9: เส้นใหม่เป็นแบบโค้ง และวาดเป็น path (ไม่ใช่เส้นตรงอย่างเดียว)',
          edge.routing === 'curved' &&
          (pb.renderer._edgeVis.get(edge.id).line.path || []).some((seg) => seg[0] === 'C'),
          'routing=' + edge.routing);
    pb._changeEdge(edge.id, { routing: 'orthogonal' });
    check('Planner บั๊ก9: สลับเป็นหักมุมฉากได้ (path มีหลายช่วง L)',
          pb.data.getEdge(edge.id).routing === 'orthogonal' &&
          (pb.renderer._edgeVis.get(edge.id).line.path || []).filter((s) => s[0] === 'L').length >= 2);
    pb._changeEdge(edge.id, { arrowStart: 'circle', arrowEnd: 'diamond' });
    check('Planner บั๊ก11: เลือกหัวลูกศรได้ทั้งสองปลาย (วาดหัว 2 ชิ้น)',
          pb.data.getEdge(edge.id).arrowStart === 'circle' &&
          pb.data.getEdge(edge.id).arrowEnd === 'diamond' &&
          pb.renderer._edgeVis.get(edge.id).heads.length === 2);
    pb._changeEdge(edge.id, { arrowStart: 'none', arrowEnd: 'arrow', routing: 'straight' });
    // [65r3-3] เลิกใช้วัตถุรับคลิก (กรอบสี่เหลี่ยมกินพื้นที่) → วัดระยะจากตัวเส้นจริงแทน
    const eSamples = pb.renderer._edgeVis.get(edge.id).samples;
    check('Planner บั๊ก10: เส้นเก็บรูปเป็นชุดจุดไว้ทดสอบการคลิกด้วยระยะจริง',
          Array.isArray(eSamples) && eSamples.length >= 2 &&
          pb.renderer.hitEdgeAt(eSamples[Math.floor(eSamples.length / 2)]) === edge.id,
          'samples=' + (eSamples ? eSamples.length : 0));
    check('Planner บั๊ก10: ไม่ใช้ perPixelTargetFind (ตัวการทำให้หน่วง)',
          pb.renderer._edgeVis.get(edge.id).line.perPixelTargetFind !== true &&
          pb.renderer._edgeVis.get(edge.id).line.evented === false);
    pb.selectEdge(edge.id);
    check('Planner บั๊ก10: คลิกเส้นแล้วเลือกได้ + เปิดคุณสมบัติเส้น',
          pb.renderer._selectedEdgeId === edge.id);
    pb._flipEdge(edge.id);
    check('Planner บั๊ก10: สลับทิศเส้นได้',
          pb.data.getEdge(edge.id).from.nodeId === nB.id && pb.data.getEdge(edge.id).to.nodeId === nA.id);
    pb._flipEdge(edge.id);

    // [บั๊ก 9] port ต้องยื่นออกนอกกรอบการ์ด และปุ่มปรับขนาดกลางขอบต้องปิด
    const visA = pb.renderer._nodeVis.get(nA.id);
    pb.renderer.showPorts(visA);
    const portsShown = pb.renderer.getObjects('port').filter((o) => o.visible);
    const rightPort = portsShown.find((o) => o.port === 'right');
    check('Planner บั๊ก9: port โผล่ 4 จุด และยื่นออกนอกขอบการ์ด (ไม่โดน transform บัง)',
          portsShown.length === 4 && !!rightPort && rightPort.left > nA.x + nA.width + 2,
          `right=${rightPort ? Math.round(rightPort.left) : '?'} edge=${nA.x + nA.width}`);
    // [alpha.65r บั๊ก 4] ปุ่มกลางขอบต้อง "เปิด" ไว้เพื่อยืดด้านเดียว — port ยื่นไกลกว่าจึงไม่ทับกัน
    check('Planner บั๊ก4: เปิดปุ่มปรับขนาดกลางขอบ + port ยังอยู่ไกลกว่าปุ่ม (ไม่ทับ)',
          visA.isControlVisible('mr') === true && visA.isControlVisible('mt') === true &&
          rightPort.left - (nA.x + nA.width) >= 10,
          'gap=' + Math.round(rightPort.left - (nA.x + nA.width)));
    check('Planner บั๊ก4: ปิดล็อกสัดส่วนตอนลากมุม (uniformScaling=false)',
          pb.renderer.canvas.uniformScaling === false);
    pb.renderer.hidePorts();
    check('Planner v4 ซ่อน port เมื่อออกจากการ์ด',
          pb.renderer.getObjects('port').filter((o) => o.visible).length === 0);

    // [บั๊ก 6] กริด
    const g0 = pb.data.getGrid();
    check('Planner บั๊ก6: มีกริดเริ่มต้น + วาดด้วย CSS บนเวที',
          g0.show === true && g0.size === 20 &&
          /gradient/.test(pb.stage.style.backgroundImage || ''), pb.stage.style.backgroundSize);
    pb.setGrid({ size: 50, snap: true, style: 'lines' });
    check('Planner บั๊ก6: ปรับขนาด/รูปแบบ/สแนปกริดได้',
          pb.data.getGrid().size === 50 && pb.data.getGrid().snap === true &&
          pb.data.getGrid().style === 'lines' &&
          /linear-gradient/.test(pb.stage.style.backgroundImage || ''));
    const snapNode = pb.data.addNode('sticky', 'สแนป', '#f2c14e', 137, 88);
    check('Planner บั๊ก6: snap ดูดพิกัดเข้าเส้นกริด (137,88 → 150,100)',
          snapNode.x === 150 && snapNode.y === 100, `${snapNode.x},${snapNode.y}`);
    pb.data.removeNode(snapNode.id);
    pb.setGrid({ size: 20, snap: false, style: 'dots', show: false });
    check('Planner บั๊ก6: ปิดกริดได้', pb.stage.style.backgroundImage === 'none');
    pb.setGrid({ show: true });

    // [บั๊ก 4] เครื่องมือแบบ Miro สร้างวัตถุได้จริง
    const madeText = pb._createFromTool('text', { x: 700, y: 120 });
    const madeShape = pb._createFromTool('shape', { x: 700, y: 260, shape: 'diamond' });
    const madeFrame = pb._createFromTool('frame', { x: 900, y: 120, box: { x: 900, y: 120, width: 400, height: 300 } });
    const madeComment = pb._createFromTool('comment', { x: 700, y: 400 });
    const madeSticky = pb._createFromTool('sticky', { x: 520, y: 520 });
    check('Planner บั๊ก4: สร้าง Text / Shape / Frame / Comment / Sticker ได้ครบ',
          madeText.type === 'text' && madeShape.type === 'shape' && madeShape.shape === 'diamond' &&
          madeFrame.type === 'frame' && madeFrame.width === 400 &&
          madeComment.type === 'comment' && madeSticky.type === 'sticky',
          [madeText.type, madeShape.shape, madeFrame.width, madeComment.type, madeSticky.type].join('/'));
    pb.interaction.setTool('hand');
    check('Planner บั๊ก4: โหมดมือปิดการเลือก + เคอร์เซอร์เป็น grab',
          pb.interaction.getTool() === 'hand' && pb.renderer.canvas.selection === false &&
          pb.renderer.canvas.defaultCursor === 'grab');
    const vpBefore = pb.renderer.getViewport().x;
