    await new Promise((r) => setTimeout(r, 30));
    check('Ctrl+, เปิดตั้งค่า (คีย์ลัด renderer ทำงาน)', !!document.querySelector('.k-settings'));
    document.querySelector('.k-settings .k-cancel')?.click();
    // Ctrl+S บันทึกแท็บที่ค้าง
