        check('[84] ตั้งค่ามีช่องกฎการตัดหน้าครบ',
              ['#st-pb-ab', '#st-pb-at', '#st-pb-db', '#st-pb-dt', '#st-pb-hy', '#st-pb-ks']
                .every((s) => !!document.querySelector('.k-settings ' + s)));
