            check('[r3-6] /// = โน้ต', els[9] === 'note' && b[9].text === 'โน้ต');
            // `---` บังคับให้ paginate ขึ้นหน้าใหม่จริง
            // paginate() คืน { pages, count } ไม่ใช่อาร์เรย์
            const pg = paginate([{ el: 'action', text: 'ก่อนคั่น' },
                                 { el: 'page-break', text: '' },
                                 { el: 'action', text: 'หลังคั่น' }], {}).pages;
